import java.net.*;import java.net.http.*;import java.nio.file.*;import java.io.*;import java.time.*;import java.util.*;
/** Disposable loopback integration tests. No production accounts or credentials. */
public class Admin750Check {
 static final String PASSWORD="local-admin-test-750-only";static HttpClient http=HttpClient.newHttpClient();static String base,cookie="";
 static void ok(boolean x,String msg){if(!x)throw new AssertionError(msg);System.out.println("PASS: "+msg);}
 static class Records extends AdminData {
  final CloudStore.Memory memory;final Map<String,Map<String,Object>> accounts=new LinkedHashMap<>();final List<Map<String,Object>> notices=new ArrayList<>();
  Records(CloudStore.Memory store)throws Exception{super(store);memory=store;for(var e:store.accounts.entrySet()){var p=e.getValue().profile();Map<String,Object> a=new HashMap<>();a.put("id",p.id);a.put("email",e.getKey());a.put("display_name",p.name);a.put("public_id",p.publicId);a.put("coins",p.coins);a.put("shopping_money",p.shoppingMoney);a.put("created_at",Instant.now().minusSeconds(86400*10).toString());a.put("last_login_at",Instant.now().minusSeconds(86400).toString());a.put("last_seen_at",Instant.now().minusSeconds(86400).toString());a.put("max_offline_seconds",172800);accounts.put(p.id,a);}}
  void delete(String id){accounts.remove(id);memory.accounts.entrySet().removeIf(e->e.getValue().profile().id.equals(id));}
  synchronized Object call(String op,Map<String,Object> d)throws Exception{String id=Json.str(d,"id");Map<String,Object> a=accounts.get(id);switch(op){
   case "accounts":String q=Json.str(d,"search");List<Map<String,Object>> rows=new ArrayList<>();for(var row:accounts.values())if(q.isEmpty()||row.toString().contains(q))rows.add(new HashMap<>(row));return new HashMap<>(Map.of("accounts",rows,"total",accounts.size(),"now",Instant.now().toString()));
   case "announcements":return new ArrayList<>(notices);
   case "announcement-save":var n=new HashMap<>(d);n.put("id",UUID.randomUUID().toString());notices.add(n);return n;
   case "announcement-delete":notices.removeIf(nc->nc.get("id").equals(id));return Map.of();
   case "schedule":a.put("delete_at",d.get("delete_at"));a.put("delete_reason",d.get("reason"));a.put("appeal",d.get("appeal"));a.put("cancel_on_login",d.get("cancel_on_login"));return Map.of();
   case "cancel-delete":a.remove("delete_at");return Map.of();
   case "delete-now":delete(id);return Map.of();
   case "presence":List<String> active=new ArrayList<>();for(Object v:(List<?>)d.get("users")){var u=Json.obj(v);var row=accounts.get(u.get("id"));if(row!=null){row.put("last_seen_at",u.get("at"));active.add((String)u.get("id"));}}return active;
   case "maintenance":for(var row:new ArrayList<>(accounts.values()))if(row.get("delete_at")!=null&&Instant.parse((String)row.get("delete_at")).isBefore(Instant.now()))delete((String)row.get("id"));return Map.of();
   case "login":if(a==null)return Map.of("blocked",true);List<Map<String,Object>> out=new ArrayList<>();if(a.get("delete_at")!=null){if(Instant.parse((String)a.get("delete_at")).isBefore(Instant.now())){delete(id);return Map.of("blocked",true);}out.add(Map.of("title","Lịch xoá tài khoản","body","Tài khoản dự kiến xoá vào 10/12/2026. Còn 5 ngày. Khiếu nại: "+a.get("appeal")));if(Boolean.TRUE.equals(a.get("cancel_on_login")))a.remove("delete_at");}for(var n2:notices)if((Json.str(n2,"target").isEmpty()||n2.get("target").equals(id))&&!Instant.parse((String)n2.get("starts_at")).isAfter(Instant.now())&&Instant.parse((String)n2.get("ends_at")).isAfter(Instant.now()))out.add(n2);a.put("last_login_at",Instant.now().toString());a.put("last_seen_at",Instant.now().toString());return Map.of("blocked",false,"notices",out);
   default:throw new IllegalArgumentException(op);
  }}
 }
 static HttpResponse<String> req(String path,Map<String,Object> body,boolean origin)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+"/admin/api/"+path));if(!cookie.isEmpty())b.header("Cookie",cookie);if(body!=null){b.header("Content-Type","application/json");if(origin)b.header("Origin",base);b.POST(HttpRequest.BodyPublishers.ofString(Json.write(body)));}return http.send(b.build(),HttpResponse.BodyHandlers.ofString());}
 static DataInputStream login(String email)throws Exception{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeInt(GunnyServer.MAGIC);out.writeUTF("login");out.writeUTF(email);out.writeUTF("test-password-123");var response=http.send(HttpRequest.newBuilder(URI.create(base+"/api")).header("X-Gunny-Admin","1").POST(HttpRequest.BodyPublishers.ofByteArray(bytes.toByteArray())).build(),HttpResponse.BodyHandlers.ofByteArray());return new DataInputStream(new ByteArrayInputStream(response.body()));}
 public static void main(String[] args)throws Exception{CloudStore.Memory store=new CloudStore.Memory();for(int i=0;i<4;i++)store.register("player"+i+"@local.test","test-password-123",new String[]{"Gunner","Xạ thủ","Pháo thủ","Hỗ trợ"}[i]);Records records=new Records(store);try(var server=new GunnyServer(new InetSocketAddress("127.0.0.1",args.length>0?8765:0),Path.of("backend/assets"),store,records,PASSWORD,true)){base="http://127.0.0.1:"+server.port();
  if(args.length>0){System.out.println("Local test preview: "+base+"/admin/");new java.util.concurrent.CountDownLatch(1).await();return;}
  ok(req("accounts",null,false).statusCode()==401,"Unauthenticated account list rejected");ok(req("login",Map.of("password",PASSWORD),false).statusCode()==403,"Cross-site login rejected");ok(req("login",Map.of("password","bad-password"),true).statusCode()==401,"Wrong password rejected");var r=req("login",Map.of("password",PASSWORD),true);cookie=r.headers().firstValue("Set-Cookie").orElseThrow().split(";")[0];ok(r.statusCode()==200&&r.headers().firstValue("Set-Cookie").get().contains("HttpOnly"),"Password creates HttpOnly restricted session");
  var list=Json.obj(Json.parse(req("accounts",null,false).body()));ok(((List<?>)list.get("accounts")).size()==4,"All registered accounts listed");String a=(String)records.accounts.values().iterator().next().get("id");String email=(String)records.accounts.get(a).get("email");
  var schedule=new HashMap<String,Object>(Map.of("id",a,"delete_at",Instant.now().plusSeconds(86400*5).toString(),"reason","Không hoạt động","appeal","https://example.invalid/appeal","cancel_on_login",false));ok(req("schedule",schedule,true).statusCode()==200,"Schedule saves date, reason and appeal contact");
  Map<String,Object> notice=new HashMap<>(Map.of("title","Thông báo thử","body","Nội dung phát trong ba ngày","target","","starts_at",Instant.now().minusSeconds(60).toString(),"ends_at",Instant.now().plusSeconds(86400*3).toString()));ok(req("announcement-save",notice,true).statusCode()==200,"Timed broadcast saved");notice.put("target",a);notice.put("title","Thông báo riêng");req("announcement-save",notice,true);
  for(int i=0;i<2;i++){var game=login(email);ok(game.readUnsignedByte()==0,"Game login accepted");game.readUTF();GunnyServer.Session player=server.sessions.values().iterator().next();var skip=new ByteArrayOutputStream();server.profile(new DataOutputStream(skip),player.profile);game.skipNBytes(skip.size());int count=game.readUnsignedByte();ok(count==3,"Deletion warning plus public and private notices appear on every login");for(int n=0;n<count;n++){game.readUTF();game.readUTF();game.readUTF();}}
  var other=(String)records.accounts.keySet().stream().filter(id->!id.equals(a)).findFirst().get();ok(((List<?>)records.login(other).get("notices")).size()==1,"Private message does not leak to another account");
  String scheduledId=(String)records.accounts.keySet().stream().filter(id->!id.equals(a)).findFirst().get();records.accounts.get(scheduledId).put("delete_at",Instant.now().minusSeconds(1).toString());server.admin.maintenance();ok(!records.accounts.containsKey(scheduledId),"Scheduled maintenance deletes due disposable account");
  ok(req("delete-now",Map.of("id",a,"confirm","bad"),true).statusCode()==400,"Permanent deletion requires explicit confirmation");ok(req("delete-now",Map.of("id",a,"confirm","XOA"),true).statusCode()==200&&server.sessions.isEmpty(),"Immediate deletion revokes active game sessions");
  ok(req("logout",Map.of(),true).statusCode()==200&&req("accounts",null,false).statusCode()==401,"Logout invalidates admin session");System.out.println("All admin 7.5.0 HTTP checks passed");
 }}
}
